func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddCases(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "positives", a: 7, b: 5, want: 12},
		{name: "negative and positive", a: -3, b: 8, want: 5},
		{name: "two negatives", a: -4, b: -6, want: -10},
		{name: "with zero", a: 0, b: 9, want: 9},
		{name: "larger values", a: 1000, b: 2500, want: 3500},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.a, tt.b); got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

